const rows = Array.isArray($json.list) ? $json.list : [];
const draftOnly = true;
const blockedStatuses = new Set(['unsubscribed', 'bounced', 'complained']);
const textFields = ['company_homepage_name', 'parent_company', 'best_url', 'canonical_domain', 'industry_guess', 'website_content', 'source_urls', 'services_detected', 'locations_detected', 'leadership_or_team_signals', 'contact_info_detected', 'structured_data_detected', 'selected_contact_name', 'selected_contact_title', 'selected_contact_role', 'selected_contact_email', 'selected_contact_linkedin_url', 'validated_email', 'unsubscribe_status', 'email_source'];
const output = [];
for (const row of rows) {
  const normalized = { ...row };
  for (const field of textFields) normalized[field] = String(normalized[field] || '').trim();
  normalized.unsubscribe_status = normalized.unsubscribe_status || 'active';
  normalized.do_not_contact = normalized.do_not_contact === true || String(normalized.do_not_contact).toLowerCase() === 'true';
  const unsub = normalized.unsubscribe_status.toLowerCase();
  const hasSendableEmail = Boolean(String(normalized.validated_email || '').trim());
  if (normalized.do_not_contact) continue;
  if (blockedStatuses.has(unsub)) continue;
  if (!hasSendableEmail) continue;
  output.push({ json: { ...normalized, draft_only: draftOnly } });
}
return output;

const output = [];
for (const [index, item] of items.entries()) {
  const plan = item.json || {};
  if (!plan.patch || !plan.record) {
    output.push({ json: { ...plan, skip_llm: true } });
    continue;
  }
  const sourceRows = $('Rows To Items').all().map((entry) => entry.json || {});
  const patchId = String(plan.patch?.Id || plan.row_id || '').trim();
  const sourceRow = sourceRows.find((candidate) => String(candidate.Id || '').trim() === patchId) || sourceRows[index] || {};
  const record = plan.record || {};
  const classification = record.classification || {};
  const copyBrief = record.copy_brief || {};
  const row = {
    ...sourceRow,
    Id: plan.patch.Id,
    company_name: sourceRow.company_name || plan.patch.company_name || classification.company_name || '',
    selected_contact_name: sourceRow.selected_contact_name || plan.patch.selected_contact_name || '',
    selected_contact_title: sourceRow.selected_contact_title || plan.patch.selected_contact_title || '',
  };
  const system = 'You write short, evidence-based cold email drafts for RAYN Secure. Use the copy brief exactly. Return strict JSON only. Do not send emails. Do not invent facts.';
  const user = {
    company_name: row.company_name || plan.row_id || '',
    selected_contact_title: row.selected_contact_title || '',
    pressure_type: classification.pressure_type,
    company_profile_summary: copyBrief.company_profile_summary,
    primary_services_summary: copyBrief.primary_services_summary,
    locations_summary: copyBrief.locations_summary,
    team_structure_summary: copyBrief.team_structure_summary,
    personal_data_handled_guess: copyBrief.personal_data_handled_guess,
    sensitive_data_examples: copyBrief.sensitive_data_examples,
    data_systems_likely: copyBrief.data_systems_likely,
    regulatory_pressure_summary: copyBrief.regulatory_pressure_summary,
    hia_obligation_angle: copyBrief.hia_obligation_angle,
    pdpa_obligation_angle: copyBrief.pdpa_obligation_angle,
    customer_trust_angle: copyBrief.customer_trust_angle,
    deadline_or_timeline_angle: copyBrief.deadline_or_timeline_angle,
    funding_claim_line: copyBrief.funding_route_summary || plan.patch.funding_claim_line,
    funding_claim_safe: copyBrief.funding_claim_safe,
    email_personalisation_signal: copyBrief.email_personalisation_signal,
    email_problem_statement: copyBrief.email_problem_statement,
    email_mechanism_statement: copyBrief.email_mechanism_statement,
    email_asset_offer: copyBrief.email_asset_offer,
    email_cta: copyBrief.email_cta,
    email_angle_reason: copyBrief.email_angle_reason,
    rules: [
      'Use the copy brief exactly. Do not invent facts.',
      'If selected_contact_name is blank or the selected email is a generic/company inbox, greet with Hi team, or Hi {{company_name}} team, and do not invent a person name.',
      'Email 1 follows this order after the greeting: email_personalisation_signal, then email_problem_statement, then email_mechanism_statement, then email_cta.',
      'Email 1 must feel like a researched note and must not start with generic noticed your company wording.',
      'Email 2 is a practical diagnostic based on email_problem_statement and data_systems_likely.',
      'Email 2 must not be a generic certification explanation.',
      'Email 3 is funding-only and must use funding_claim_line verbatim.',
      'Email 4 closes the loop and references email_asset_offer.',
      'Do not say if you are an SME or if you are an NPO.',
      'Do not say eligible SMEs and NPOs may.',
      'Do not claim guaranteed funding.',
      'Do not say Cyber Essentials makes the company PDPA compliant.',
      'Do not say Cyber Essentials completes HIA compliance.',
      'Keep Email 1 <= 85 words, Email 2 <= 80, Email 3 <= 95, Email 4 <= 55.',
      'Use one tiny CTA per email.'
    ],
    return_shape: {
      email_1: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_2: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_3: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_4: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      evidence_used: [],
      claims_avoided: [],
      quality_notes: []
    }
  };
  output.push({
    json: {
      row: row,
      planner_result: plan,
      body: {
        model: 'anthropic/claude-sonnet-4.6',
        temperature: 0.2,
        max_tokens: 1800,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: JSON.stringify(user) }
        ],
        response_format: { type: 'json_object' }
      }
    }
  });
}
return output;

const output = [];
for (let index = 0; index < items.length; index++) {
  const response = items[index].json || {};
  const prepared = $('Prepare OpenRouter Email Draft').all()[index]?.json || {};
  output.push({ json: { ...prepared, openrouter_response: response } });
}
return output;

function wordCount(text) {
  return String(text || '').match(/\b[\w'-]+\b/g)?.length || 0;
}
function parseFlags(value) {
  try { return Array.isArray(value) ? value : JSON.parse(value || '[]'); } catch (error) { return value ? [String(value)] : []; }
}
function auditFromPatch(patch, prior = {}) {
  return {
    row_id: patch.Id || prior.row_id || '',
    company_name: prior.company_name || patch.company_name || '',
    pressure_type: patch.pressure_type || prior.pressure_type || '',
    hia_service_type_guess: patch.hia_service_type_guess || prior.hia_service_type_guess || '',
    hia_timeline_batch_guess: patch.hia_timeline_batch_guess || prior.hia_timeline_batch_guess || '',
    funding_status: patch.funding_status || prior.funding_status || '',
    email_quality_flags: parseFlags(patch.email_quality_flags || prior.email_quality_flags),
    email_1_body: patch.email_1_body || prior.email_1_body || '',
    email_2_body: patch.email_2_body || prior.email_2_body || '',
    email_3_body: patch.email_3_body || prior.email_3_body || '',
  };
}
function ensureFundingClaim(patch) {
  if (patch.pressure_type === 'not_ready') return patch;
  const claim = String(patch.funding_claim_line || '').trim();
  if (!claim) return patch;
  const body = String(patch.email_3_body || '');
  if (body.includes(claim)) return patch;
  const replacement = ['Hi,', '', claim, '', 'This is subject to programme confirmation.', '', 'Should I send the route summary?', '', 'Best,', 'SK', 'RAYN Secure'].join('\n');
  let flags = [];
  try { flags = JSON.parse(patch.email_quality_flags || '[]'); } catch (error) { flags = []; }
  flags = flags.filter((flag) => flag !== 'email_3_missing_funding_claim_line');
  let sequenceJson = patch.email_sequence_json;
  try {
    const sequence = JSON.parse(patch.email_sequence_json || '{}');
    if (sequence.email_3) {
      sequence.email_3.body = replacement;
      sequence.email_3.word_count = wordCount(replacement);
      sequenceJson = JSON.stringify(sequence);
    }
  } catch (error) {}
  return { ...patch, email_3_body: replacement, email_sequence_json: sequenceJson, email_quality_flags: JSON.stringify(flags) };
}
const patches = [];
const audits = [];
const errors = [];
for (const item of items) {
  const body = item.json || {};
  if (body.patch && body.patch.Id) {
    const patch = ensureFundingClaim(body.patch);
    patches.push(patch);
    audits.push(auditFromPatch(patch, body.audit_report || {}));
  } else {
    errors.push({ row_id: body.row_id || '', error: body.error || 'missing_patch' });
  }
}
return [{ json: { patches, audits, errors, count: patches.length } }];
